CREATE COLUMN TABLE "TEST_AP"."ITM12" ("ItemCode" NVARCHAR(50) NOT NULL , "UomType" NVARCHAR(1) DEFAULT 'P' NOT NULL , "UomEntry" INTEGER CS_INT NOT NULL , "BcdEntDft" INTEGER CS_INT, "PkgCodeDft" INTEGER CS_INT, "Height1" DECIMAL(21,6) CS_FIXED, "Hght1Unit" SMALLINT CS_INT, "Height2" DECIMAL(21,6) CS_FIXED, "Hght2Unit" SMALLINT CS_INT, "Width1" DECIMAL(21,6) CS_FIXED, "Wdth1Unit" SMALLINT CS_INT, "Width2" DECIMAL(21,6) CS_FIXED, "Wdth2Unit" SMALLINT CS_INT, "Length1" DECIMAL(21,6) CS_FIXED, "Len1Unit" SMALLINT CS_INT, "Length2" DECIMAL(21,6) CS_FIXED, "Len2Unit" SMALLINT CS_INT, "Volume" DECIMAL(21,6) CS_FIXED, "VolUnit" SMALLINT CS_INT, "Weight1" DECIMAL(21,6) CS_FIXED, "Wght1Unit" SMALLINT CS_INT, "Weight2" DECIMAL(21,6) CS_FIXED, "Wght2Unit" SMALLINT CS_INT, PRIMARY KEY ("ItemCode", "UomType", "UomEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
